package in.guvi.fraud.service;
import in.guvi.fraud.dao.TransactionDao;import in.guvi.fraud.model.Transaction;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
public class DetectionService {
 private final TransactionDao dao;private final MlFraudModel model;public DetectionService(TransactionDao d,MlFraudModel m){dao=d;model=m;}
 public void evaluate(Transaction t)throws Exception{t.createdAt=LocalDateTime.now();int n=dao.recent(t.customerId,t.createdAt);String l=t.location.toLowerCase(Locale.ROOT),m=t.paymentMethod.toLowerCase(Locale.ROOT);int h=(l.contains("high-risk")||l.contains("unknown"))?1:0,u=(m.contains("unverified")||m.contains("gift"))?1:0;double prob=model.probability(t.amount.doubleValue(),h,u,n);int score=(int)Math.round(prob*100);List<String> why=new ArrayList<>();if(t.amount.compareTo(new BigDecimal("50000"))>=0){score=Math.max(score,35);why.add("Very large amount");}else if(t.amount.compareTo(new BigDecimal("20000"))>=0)why.add("Elevated amount");if(h==1){score=Math.max(score,30);why.add("High-risk/unknown location");}if(u==1){score=Math.max(score,20);why.add("Payment method requires verification");}if(n>=3){score=Math.max(score,30);why.add("Repeated activity in one hour");}if(why.isEmpty())why.add("No configured risk indicators detected");t.riskScore=Math.min(score,100);int check=dao.setting("check",30),review=dao.setting("review",60);t.decision=t.riskScore>=review?"REVIEW":t.riskScore>=check?"CHECK":"APPROVED";t.explanation=String.join("; ",why)+"; ML fraud probability "+String.format(Locale.US,"%.0f%%",prob*100);}
}
